findings.codeql_raw_query:
/**
 * @name User-controlled setattr attribute
 * @description Detects if the attribute name in setattr is influenced by function arguments
 * @kind path-problem
 * @problem.severity warning
 * @id py/tainted-setattr
 * @tags security
 *       external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SetattrTaintConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("setattr").getACall() and
      sink = call.getArg(1)
    )
  }
}

module SetattrTaintFlow = TaintTracking::Global<SetattrTaintConfig>;
import SetattrTaintFlow::PathGraph

from SetattrTaintFlow::PathNode source, SetattrTaintFlow::PathNode sink
where SetattrTaintFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Attribute name in setattr depends on function parameter $@", source.getNode(), "param"
